I can implement this, but I need two repo-specific details to avoid deleting the wrong things:

1) Where are the **source templates** (path + extension), and how do we **render** them (copy, unzip, ImageMagick, ffmpeg, a custom generator, etc.)?  
2) Which **asset output directories** are safe to wipe/rebuild (or should it be derived from templates)?

In the meantime, here’s a solid, safe implementation pattern you can drop into your repo as a CLI command. It:
- finds template files,
- computes their output paths,
- deletes only the corresponding generated outputs (recursively),
- recreates them by running a generator,
- supports `--dry-run` and `--force`.

## Option A: Node CLI (recommended) — `scripts/assets-rebuild.mjs`

```js
#!/usr/bin/env node
import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";

const args = new Set(process.argv.slice(2));
const DRY = args.has("--dry-run");
const FORCE = args.has("--force");

const repoRoot = process.cwd();

// CONFIG: adjust to your repo
const TEMPLATE_ROOTS = ["assets-src"];              // where templates live
const TEMPLATE_EXTS = new Set([".template"]);       // template suffix
const OUT_ROOT = "assets";                          // generated assets root

// Map a template path -> output directory (or file) path.
// Example: assets-src/foo/bar.template -> assets/foo/bar
function templateToOut(templateRelPath) {
  const rel = templateRelPath.replaceAll("\\", "/");
  const within = rel.startsWith("assets-src/") ? rel.slice("assets-src/".length) : rel;
  const base = within.replace(/\.template$/, "");
  return path.join(OUT_ROOT, base);
}

// Generator: replace this with your real renderer.
// For now it just copies template -> output (as a placeholder).
async function generateFromTemplate(templateAbs, outAbs) {
  await fs.mkdir(path.dirname(outAbs), { recursive: true });
  // Placeholder behavior: copy the template to outAbs + ".bin"
  // Change as needed: unzip, transcode, render, etc.
  const outFile = outAbs.endsWith(".bin") ? outAbs : outAbs + ".bin";
  await fs.mkdir(path.dirname(outFile), { recursive: true });
  await fs.copyFile(templateAbs, outFile);
}

async function pathExists(p) {
  try { await fs.stat(p); return true; } catch { return false; }
}

async function rmRecursiveSafe(p) {
  // Safety guard: only delete within OUT_ROOT
  const outRootAbs = path.resolve(repoRoot, OUT_ROOT) + path.sep;
  const targetAbs = path.resolve(p);
  if (!targetAbs.startsWith(outRootAbs)) {
    throw new Error(`Refusing to delete outside ${OUT_ROOT}: ${targetAbs}`);
  }
  if (DRY) return;
  await fs.rm(targetAbs, { recursive: true, force: true });
}

async function walk(dirAbs, out = []) {
  const ents = await fs.readdir(dirAbs, { withFileTypes: true });
  for (const e of ents) {
    const p = path.join(dirAbs, e.name);
    if (e.isDirectory()) await walk(p, out);
    else out.push(p);
  }
  return out;
}

function isTemplateFile(absPath) {
  return TEMPLATE_EXTS.has(path.extname(absPath));
}

async function main() {
  if (!FORCE && !DRY) {
    console.error(
      `Refusing to run without --force (this deletes generated assets under "${OUT_ROOT}/").\n` +
      `Use --dry-run to preview.`
    );
    process.exit(2);
  }

  // Collect templates
  const templates = [];
  for (const root of TEMPLATE_ROOTS) {
    const abs = path.resolve(repoRoot, root);
    if (!(await pathExists(abs))) continue;
    const files = await walk(abs);
    for (const f of files) if (isTemplateFile(f)) templates.push(f);
  }

  if (templates.length === 0) {
    console.log("No templates found.");
    return;
  }

  // Compute outputs
  const jobs = templates.map((tAbs) => {
    const tRel = path.relative(repoRoot, tAbs);
    const outRel = templateToOut(tRel);
    const outAbs = path.resolve(repoRoot, outRel);
    return { tAbs, tRel, outRel, outAbs };
  });

  // Delete outputs (recursively) then rebuild
  console.log(`${DRY ? "[dry-run] " : ""}Templates: ${templates.length}`);
  for (const j of jobs) {
    if (await pathExists(j.outAbs)) {
      console.log(`${DRY ? "[dry-run] " : ""}rm -r ${j.outRel}`);
      await rmRecursiveSafe(j.outAbs);
    }
  }

  for (const j of jobs) {
    console.log(`${DRY ? "[dry-run] " : ""}gen ${j.tRel} -> ${j.outRel}`);
    if (!DRY) await generateFromTemplate(j.tAbs, j.outAbs);
  }

  console.log("Done.");
}

main().catch((err) => {
  console.error(err?.stack || String(err));
  process.exit(1);
});
```

Add to `package.json`:

```json
{
  "scripts": {
    "assets:rebuild": "node scripts/assets-rebuild.mjs --force",
    "assets:rebuild:dry": "node scripts/assets-rebuild.mjs --dry-run"
  }
}
```

## Option B: Make it Git-friendly
If these are generated binaries you don’t want in git, pair this with:
- `.gitignore` for `assets/` (or selected subfolders)
- CI step: run `npm run assets:rebuild`

